by @C0 + C1 * u + C2 * u^2 + C3 * u^3 + C4 * u^4 + C5 * u^5@. Units (both
parities): C0 in 2^-55, C1 in 2^-47, C2 in 2^-39, C3 in 2^-32, C4 in 2^-23 and
C5 in 2^-15. Absolute error, Chebyshev nodes and LLL with delta 3/4, like the
exponential.

